function C(n,t){return t==="1rm"?Math.round(n.topWeight*(1+n.topReps/30)*10)/10:n.topWeight}function M(n){if(n==="all")return null;let t=new Date;return t.setMonth(t.getMonth()-(n==="3m"?3:6)),`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}-${String(t.getDate()).padStart(2,"0")}`}function $(n,t){let a=n.length,o=Math.min(...t),i=Math.max(...t),x=i-o||1,r=t.map((e,y)=>({x:32+y/Math.max(a-1,1)*260,y:88-(e-o)/x*80})),s=r.map(e=>`${e.x.toFixed(1)},${e.y.toFixed(1)}`).join(" "),l=[`M${r[0].x.toFixed(1)},88`,...r.map(e=>`L${e.x.toFixed(1)},${e.y.toFixed(1)}`),`L${r[r.length-1].x.toFixed(1)},88Z`].join(" "),p=[{value:o,y:88},{value:i,y:14}],u=[...new Set([0,Math.floor((a-1)/2),a-1])].map(e=>({label:n[e].dateISO.slice(5),x:r[e].x}));return{pts:r,points:s,areaPath:l,yLabels:p,xLabels:u}}export{C as a,M as b,$ as c};
